import{_ as t,C as r,o as e,c as d,a2 as n,j as i,E as s,a as o}from"./chunks/framework.C21TwvGF.js";const j=JSON.parse('{"title":"5-dars (Mentor). Android ekotizimi va Google xizmatlari (2-qism)","description":"","frontmatter":{"title":"5-dars (Mentor). Android ekotizimi va Google xizmatlari (2-qism)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Android)","link":"/mentor/9-sinf-android/"},"week":{"n":2,"link":"/mentor/9-sinf-android/hafta-02/"},"g":5,"title":"Android ekotizimi va Google xizmatlari (2-qism)","lead":"Android ekotizimi va Google xizmatlari (2-qism): Google Play Console, SHA-1 barmoq izi, xavfsizlik va AAB formati","slide":"/slaydlar/9-sinf-android/hafta-02/dars-2.html","test":"/slaydlar/9-sinf-android/hafta-02/dars-2-test.html","student_link":"/9-sinf-android/hafta-02/dars-2","tabs":[{"g":4,"link":"/mentor/9-sinf-android/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/9-sinf-android/hafta-02/dars-2","current":true},{"g":6,"link":"/mentor/9-sinf-android/hafta-02/dars-3","current":false}],"prev":{"g":4,"title":"Android ekotizimi va Google xizmatlari (1-qism)","link":"/mentor/9-sinf-android/hafta-02/dars-1"},"next":{"g":6,"title":"Android Studio va Android SDK bilan tanishuv (1-qism)","link":"/mentor/9-sinf-android/hafta-02/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-android/hafta-02/dars-2.md","filePath":"mentor/9-sinf-android/hafta-02/dars-2.md"}'),h={name:"mentor/9-sinf-android/hafta-02/dars-2.md"},g={class:"blk"},u={id:"_1-dars-maqsadi-va-kutiladigan-natijalar",tabindex:"-1"},c={class:"blk"},m={id:"_2-dars-rejasi-80-daqiqa",tabindex:"-1"},p={class:"blk"},b={id:"_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt",tabindex:"-1"},y={class:"blk"},k={id:"_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari",tabindex:"-1"},v={class:"blk"},q={id:"_5-tezkor-savol-javob-blits-savollar",tabindex:"-1"},f={class:"blk"},A={id:"_6-mentor-uchun-amaliy-tavsiyalar",tabindex:"-1"};function _(z,a,x,P,S,I){const l=r("Icon");return e(),d("div",null,[a[18]||(a[18]=n("<p><strong>Sinf:</strong> 9-sinf (Android dasturlash)<br><strong>Hafta:</strong> 2-hafta<br><strong>Dars tartibi:</strong> 5-dars (umumiy 102 darsdan 5-darsi)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Format:</strong> Amaliy va xavfsizlikka yo&#39;naltirilgan mashg&#39;ulot</p><hr>",2)),i("div",g,[i("h2",u,[s(l,{name:"file-text"}),a[0]||(a[0]=o(" 1. Dars maqsadi va kutiladigan natijalar ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-maqsadi-va-kutiladigan-natijalar","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars maqsadi va kutiladigan natijalar"'},"​",-1))]),a[2]||(a[2]=n("<ul><li><strong>Maqsad:</strong> O&#39;quvchilarga Google xizmatlarini (Firebase, Google Cloud) mobil loyihaga professional darajada ulash tartibi, SHA-1 raqamli barmoq izini olish, <code>google-services.json</code> fayli bilan ishlash, API kalitlari xavfsizligi hamda APK va AAB formatlari farqini o&#39;rgatish.</li><li><strong>Kutiladigan natijalar:</strong><ul><li>O&#39;quvchi ilovaning noyob identifikatori (<code>applicationId</code> / Package Name) nima ekanini biladi;</li><li>Terminal orqali <code>./gradlew signingReport</code> buyrug&#39;i bilan SHA-1 va SHA-256 barmoq izlarini mustaqil ola biladi;</li><li><code>google-services.json</code> faylining vazifasi va loyiha papkasidagi o&#39;rnini (<code>app/</code> katalogi) tushunadi;</li><li>API kalitlarini ochiq kodda qoldirmasdan <code>local.properties</code> orqali xavfsiz saqlash amaliyotini o&#39;zlashtiradi;</li><li>APK va AAB (Android App Bundle) formatlari o&#39;rtasidagi farqni va nima uchun Google Play AAB talab qilishini tushuntira oladi.</li></ul></li></ul><hr>",2))]),i("div",c,[i("h2",m,[s(l,{name:"file-text"}),a[3]||(a[3]=o(" 2. Dars rejasi (80 daqiqa) ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars rejasi (80 daqiqa)"'},"​",-1))]),a[5]||(a[5]=n('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 daq</strong></td><td>O&#39;tgan mavzuni takrorlash va kirish</td><td>AOSP vs GMS, Google Play Services vazifalari bo&#39;yicha blits-so&#39;rov. Muammoli savol: &quot;Google sizning ilovangiz aynan sizga tegishli ekanini qayerdan biladi?&quot;</td></tr><tr><td><strong>10–30 daq</strong></td><td>Yangi mavzu: Identifikatsiya va SHA-1</td><td><code>applicationId</code> tuzilmasi, Keystore tushunchasi, <code>./gradlew signingReport</code> buyrug&#39;i orqali SHA-1 olish</td></tr><tr><td><strong>30–50 daq</strong></td><td>Yangi mavzu: google-services.json va xavfsizlik</td><td>Firebase Console, <code>google-services.json</code> faylining strukturasi, API kalitlarini <code>local.properties</code>da yashirish</td></tr><tr><td><strong>50–65 daq</strong></td><td>Yangi mavzu: APK vs AAB</td><td>An&#39;anaviy APK va zamonaviy Android App Bundle (AAB), Play Store&#39;ning dinamik yetkazib berish (Dynamic Delivery) mexanizmi</td></tr><tr><td><strong>65–75 daq</strong></td><td>Amaliy mashq va keys tahlili</td><td>SHA-1 kalitini tahlil qilish, loyiha fayllari ierarxiyasida to&#39;g&#39;ri joylashtirish mashqi</td></tr><tr><td><strong>75–80 daq</strong></td><td>Xulosa va baholash</td><td>Dars yakunlari, o&#39;quvchilarni baholash, uyga vazifa berish</td></tr></tbody></table><hr>',2))]),i("div",p,[i("h2",b,[s(l,{name:"file-text"}),a[6]||(a[6]=o(" 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt) ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-nazariy-tushunchalar-mentor-uchun-to-liq-konspekt","aria-label":`Permalink to "<Icon name="file-text" /> 3. Nazariy tushunchalar (Mentor uchun to'liq konspekt)"`},"​",-1))]),a[8]||(a[8]=n(`<h3 id="_3-1-ilova-identifikatori-applicationid" tabindex="-1">3.1. Ilova identifikatori: <code>applicationId</code> <a class="header-anchor" href="#_3-1-ilova-identifikatori-applicationid" aria-label="Permalink to &quot;3.1. Ilova identifikatori: \`applicationId\`&quot;">​</a></h3><p>Har bir Android ilovasi global miqyosda (Google Play&#39;da) yagona bo&#39;lgan identifikatorga ega bo&#39;lishi shart. U domen nomining teskari ko&#39;rinishida (Reverse Domain Name notation) belgilanadi:</p><ul><li><code>com.companyname.appname</code> (masalan, <code>uz.click.clickuz</code>, <code>com.payme.uz</code>).</li><li>Ushbu nom ilova o&#39;rnatilganda Linux foydalanuvchisi va uning shaxsiy ma&#39;lumotlar papkasi nomini belgilaydi (<code>/data/data/uz.click.clickuz/</code>).</li></ul><h3 id="_3-2-raqamli-barmoq-izi-sha-1-va-sha-256" tabindex="-1">3.2. Raqamli barmoq izi: SHA-1 va SHA-256 <a class="header-anchor" href="#_3-2-raqamli-barmoq-izi-sha-1-va-sha-256" aria-label="Permalink to &quot;3.2. Raqamli barmoq izi: SHA-1 va SHA-256&quot;">​</a></h3><p>Ilovani Google Cloud yoki Firebase&#39;ga ulash uchun uning &quot;raqamli shaxsini&quot; tasdiqlash talab etiladi. Buning uchun kompyuterdagi debug yoki release kalitining (Keystore) xesh qiymati olinadi.</p><ul><li><strong>Qanday olinadi?</strong> Android Studio ichidagi terminal oynasida:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">./gradlew</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> signingReport</span></span></code></pre></div></li><li><strong>Natija:</strong><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Variant: debugAndroidTest</span></span>
<span class="line"><span>Config: debug</span></span>
<span class="line"><span>Store: /Users/dev/.android/debug.keystore</span></span>
<span class="line"><span>Alias: AndroidDebugKey</span></span>
<span class="line"><span>MD5:  A1:B2:C3:...</span></span>
<span class="line"><span>SHA1: 4B:12:8A:99:32:DE:01:...</span></span>
<span class="line"><span>SHA-256: 7F:89:AB:...</span></span></code></pre></div></li></ul><p>Ushbu SHA-1 kaliti Firebase Console yoki Google Cloud Console&#39;ga kiritiladi. Bu boshqa hech kim sizning nomingizdan API so&#39;rov yubora olmasligini kafolatlaydi.</p><h3 id="_3-3-google-services-json-fayli" tabindex="-1">3.3. <code>google-services.json</code> fayli <a class="header-anchor" href="#_3-3-google-services-json-fayli" aria-label="Permalink to &quot;3.3. \`google-services.json\` fayli&quot;">​</a></h3><p>Google loyihani ro&#39;yxatdan o&#39;tkazgach, dasturchiga maxsus <code>google-services.json</code> faylini beradi. Bu fayl loyihaning &quot;guvohnomasi&quot; bo&#39;lib, quyidagilarni o&#39;z ichiga oladi:</p><ul><li><code>project_id</code> — Firebase loyihasi nomi;</li><li><code>current_key</code> — API kalitlar;</li><li><code>firebase_url</code> — ma&#39;lumotlar bazasi manzili;</li><li><code>package_name</code> — sizning <code>applicationId</code>ingiz.</li></ul><p><strong>Joylashuvi:</strong> Fayl qat&#39;iy ravishda Android loyihasining <code>app/</code> papkasi ichiga joylashtirilishi shart! Agar u noto&#39;g&#39;ri joyga qo&#39;yilsa, Gradle loyihani yig&#39;ishdan bosh tortadi.</p><h3 id="_3-4-api-kalitlari-va-xavfsizlik-security-best-practices" tabindex="-1">3.4. API kalitlari va xavfsizlik (Security Best Practices) <a class="header-anchor" href="#_3-4-api-kalitlari-va-xavfsizlik-security-best-practices" aria-label="Permalink to &quot;3.4. API kalitlari va xavfsizlik (Security Best Practices)&quot;">​</a></h3><p>Google Maps yoki boshqa xizmatlarning API kalitlarini hech qachon ochiq kodda (<code>MainActivity.kt</code>) yoki <code>AndroidManifest.xml</code>da to&#39;g&#39;ridan-to&#39;g&#39;ri yozib qoldirmaslik kerak!</p><ul><li><strong>Sababi:</strong> Agar kod GitHubga yuklansa, xakerlar maxsus botlar orqali kalitni bir necha soniyada o&#39;g&#39;irlab oladi va sizning billing hisobingizdan minglab dollar sarflab yuborishi mumkin.</li><li><strong>Xavfsiz usul:</strong> API kalitlarni <code>local.properties</code> faylida saqlash:<div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0000FF;--shiki-dark:#569CD6;">MAPS_API_KEY</span><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;">=AIzaSyD-namuna-kalit-12345</span></span></code></pre></div><code>local.properties</code> fayli avtomatik tarzda <code>.gitignore</code> ro&#39;yxatiga kiritilgan bo&#39;lib, GitHubga yuklanmaydi. Gradle orqali esa ushbu kalit xavfsiz holda <code>BuildConfig</code> orqali kodga uzatiladi.</li></ul><h3 id="_3-5-apk-vs-aab-android-app-bundle" tabindex="-1">3.5. APK vs AAB (Android App Bundle) <a class="header-anchor" href="#_3-5-apk-vs-aab-android-app-bundle" aria-label="Permalink to &quot;3.5. APK vs AAB (Android App Bundle)&quot;">​</a></h3><ul><li><strong>APK (Android Package Kit):</strong><ul><li>An&#39;anaviy arxiv fayl (.zip formatida).</li><li>Barcha protsessor arxitekturalari (arm64-v8a, armeabi-v7a, x86_64) va barcha ekran o&#39;lchamlari (hdpi, xhdpi, xxhdpi) resurslarini bitta faylda saqlaydi. Hajmi katta bo&#39;ladi (masalan, 60 MB).</li></ul></li><li><strong>AAB (Android App Bundle):</strong><ul><li>2021-yil avgust oyidan boshlab Google Play barcha yangi ilovalar uchun AAB formatini majburiy qilib qo&#39;ydi.</li><li>AAB Google Play do&#39;koniga yuklanadi. Play Store har bir foydalanuvchining telefon modelini aniqlaydi va unga faqat o&#39;sha telefon tushunadigan kod va rasmlarni jo&#39;natadi (<strong>Dynamic Delivery</strong>).</li><li>Natijada ilova hajmi <strong>30-50% ga qisqaradi</strong> (masalan, 60 MB o&#39;rniga telefon 25 MB yuklab oladi).</li></ul></li></ul><hr>`,17))]),i("div",y,[i("h2",k,[s(l,{name:"file-text"}),a[9]||(a[9]=o(" 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-darsda-bajariladigan-amaliy-topshiriqlar-va-yechimlari","aria-label":'Permalink to "<Icon name="file-text" /> 4. Darsda bajariladigan amaliy topshiriqlar va yechimlari"'},"​",-1))]),a[11]||(a[11]=n('<h3 id="_1-topshiriq-applicationid-tuzish-qoidalari-oson" tabindex="-1">1-topshiriq. <code>applicationId</code> tuzish qoidalari (Oson) <a class="header-anchor" href="#_1-topshiriq-applicationid-tuzish-qoidalari-oson" aria-label="Permalink to &quot;1-topshiriq. `applicationId` tuzish qoidalari (Oson)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Maktabingiz uchun «Kutubxona» nomli mobil ilova yaratmoqchisiz. Domen: <code>navoiy-maktab.uz</code>. Ushbu ilova uchun to&#39;g&#39;ri <code>applicationId</code> yozing.</p><p><strong>Yechim:</strong> Domen teskari tartibda yoziladi: <code>uz.navoiy_maktab.kutubxona</code> yoki <code>uz.navoiyschool.library</code>. (Eslatma: nomda bo&#39;sh joy va chiziqcha <code>-</code> ishlatilmaydi, faqat kichik lotin harflari, raqamlar va tagchiziq <code>_</code> bo&#39;lishi mumkin).</p><h3 id="_2-topshiriq-sha-1-olish-va-vazifasi-o-rta" tabindex="-1">2-topshiriq. SHA-1 olish va vazifasi (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-sha-1-olish-va-vazifasi-o-rta" aria-label="Permalink to &quot;2-topshiriq. SHA-1 olish va vazifasi (O&#39;rta)&quot;">​</a></h3><p><strong>Topshiriq:</strong> <code>./gradlew signingReport</code> buyrug&#39;i qanday ishlaydi va undan olingan SHA-1 nimani kafolatlaydi?</p><p><strong>Yechim:</strong> Buyruq Gradle orqali kompyuterdagi <code>.android/debug.keystore</code> faylini ochadi va uning ochiq kalit sertifikatining SHA-1 xeshini chiqarib beradi. Ushbu xesh Firebase yoki Google Cloud&#39;ga kiritilganda, Google faqat shu kompyuterda imzolangan ilova so&#39;rovlarini qabul qiladi, boshqa noma&#39;lum manbadan kelgan so&#39;rovlarni rad etadi.</p><h3 id="_3-topshiriq-apk-va-aab-taqqoslashi-qiyin" tabindex="-1">3-topshiriq. APK va AAB taqqoslashi (Qiyin) <a class="header-anchor" href="#_3-topshiriq-apk-va-aab-taqqoslashi-qiyin" aria-label="Permalink to &quot;3-topshiriq. APK va AAB taqqoslashi (Qiyin)&quot;">​</a></h3><p><strong>Topshiriq:</strong> Nima uchun Google Play dasturchilardan tayyor APK o&#39;rniga AAB formatini talab qiladi? Foydalanuvchi va dasturchi nuqtai nazaridan afzalliklarini tushuntiring.</p><p><strong>Yechim:</strong></p><ol><li><strong>Foydalanuvchi uchun:</strong> Ilova hajmi 30-50% kichik bo&#39;ladi. Mobil internet trafiki tejaladi, telefon xotirasi to&#39;lib qolmaydi va ilova tezroq o&#39;rnatiladi.</li><li><strong>Dasturchi uchun:</strong> Dasturchi har bir protsessor (ARM, x86) va ekran zichligi uchun alohida 5-6 xil APK yig&#39;ib o&#39;tirmaydi. U bitta umumiy AAB faylini yuklaydi, qolgan hamma optimallashuvni Google Play Store avtomatlashtiradi.</li></ol><hr>',11))]),i("div",v,[i("h2",q,[s(l,{name:"file-text"}),a[12]||(a[12]=o(" 5. Tezkor savol-javob (Blits-savollar) ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-tezkor-savol-javob-blits-savollar","aria-label":'Permalink to "<Icon name="file-text" /> 5. Tezkor savol-javob (Blits-savollar)"'},"​",-1))]),a[14]||(a[14]=n("<ol><li><strong>Android Studio terminalida SHA-1 olish buyrug&#39;i qaysi?</strong><br><em>Javob:</em> <code>./gradlew signingReport</code> (Windowsda <code>gradlew signingReport</code>).</li><li><strong><code>google-services.json</code> fayli loyihaning qaysi jildiga qo&#39;yiladi?</strong><br><em>Javob:</em> <code>app/</code> papkasi ichiga.</li><li><strong>Nima uchun maxfiy API kalitlarni <code>MainActivity</code>da qoldirish xavfli?</strong><br><em>Javob:</em> Kod GitHubga yoki begona qo&#39;lga tushganda, kalit o&#39;g&#39;irlanib, billing hisobidan noqonuniy foydalanilishi mumkin.</li><li><strong>API kalitlarini xavfsiz saqlash uchun qaysi fayldan foydalaniladi?</strong><br><em>Javob:</em> <code>local.properties</code> faylidan (chunki u <code>.gitignore</code>da bo&#39;ladi).</li><li><strong>AAB qisqartmasi nimani anglatadi?</strong><br><em>Javob:</em> Android App Bundle.</li></ol><hr>",2))]),i("div",f,[i("h2",A,[s(l,{name:"file-text"}),a[15]||(a[15]=o(" 6. Mentor uchun amaliy tavsiyalar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-mentor-uchun-amaliy-tavsiyalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun amaliy tavsiyalar"'},"​",-1))]),a[17]||(a[17]=i("ul",null,[i("li",null,[o("O'quvchilarga terminalda "),i("code",null,"./gradlew signingReport"),o(" buyrug'ining ishlashini ekranda amalda ko'rsating.")]),i("li",null,[o('SHA-1 kalitini "raqamli pasport"ga, '),i("code",null,"google-services.json"),o(' faylini esa "viza ruxsatnomasi"ga qiyoslab tushuntiring.')])],-1))])])}const B=t(h,[["render",_]]);export{j as __pageData,B as default};
